CREATE TABLE IF NOT EXISTS subcontract_boqs(id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,subcontract_id BIGINT UNSIGNED NOT NULL,status VARCHAR(20) NOT NULL DEFAULT 'draft',approved_at DATETIME NULL,approved_by BIGINT UNSIGNED NULL,notes TEXT NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,UNIQUE KEY uq_subcontract_boqs_subcontract(subcontract_id),CONSTRAINT fk_subcontract_boqs_subcontract FOREIGN KEY(subcontract_id) REFERENCES subcontracts(id) ON DELETE RESTRICT,CONSTRAINT fk_subcontract_boqs_approved_by FOREIGN KEY(approved_by) REFERENCES users(id) ON DELETE RESTRICT,CONSTRAINT chk_subcontract_boqs_status CHECK(status IN('draft','approved'))) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
